def _draw_fullscreen_icon(size=96, color="white", stroke=8):
    # No fullscreen/expand icon ships in resource.qrc - drawn instead of
    # adding a new binary asset (would need pyrcc5 + keeping qt5_ui's and
    # intelijet_v2_ws's compiled resource copies in sync).
    pixmap = QtGui.QPixmap(size, size)
    pixmap.fill(QtCore.Qt.transparent)
    painter = QtGui.QPainter(pixmap)
    painter.setRenderHint(QtGui.QPainter.Antialiasing)
    pen = QtGui.QPen(QtGui.QColor(color))
    pen.setWidth(stroke)
    pen.setCapStyle(QtCore.Qt.RoundCap)
    painter.setPen(pen)
    m = size * 0.10
    arm = size * 0.30
    corners = [
        ((m, m + arm), (m, m), (m + arm, m)),
        ((size - m - arm, m), (size - m, m), (size - m, m + arm)),
        ((m, size - m - arm), (m, size - m), (m + arm, size - m)),
        ((size - m - arm, size - m), (size - m, size - m), (size - m, size - m - arm)),
    ]
    for p1, p2, p3 in corners:
        painter.drawLine(QtCore.QPointF(*p1), QtCore.QPointF(*p2))
        painter.drawLine(QtCore.QPointF(*p2), QtCore.QPointF(*p3))
    painter.end()
    return QtGui.QIcon(pixmap)


def _icon_painter(size, color, stroke):
    pixmap = QtGui.QPixmap(size, size)
    pixmap.fill(QtCore.Qt.transparent)
    painter = QtGui.QPainter(pixmap)
    painter.setRenderHint(QtGui.QPainter.Antialiasing)
    pen = QtGui.QPen(QtGui.QColor(color))
    pen.setWidth(stroke)
    pen.setCapStyle(QtCore.Qt.RoundCap)
    pen.setJoinStyle(QtCore.Qt.RoundJoin)
    painter.setPen(pen)
    painter.setBrush(QtCore.Qt.NoBrush)
    return pixmap, painter


def _draw_cube_icon(size=96, color="white", stroke=6):
    """Side-nav icon for the 3D MAIN tab: isometric cube (hexagon + inner Y)."""
    pixmap, painter = _icon_painter(size, color, stroke)
    cx, cy = size / 2, size / 2
    r = size * 0.42
    pts = []
    for i in range(6):
        angle = math.radians(60 * i - 90)
        pts.append(QtCore.QPointF(cx + r * math.cos(angle), cy + r * math.sin(angle)))
    for i in range(6):
        painter.drawLine(pts[i], pts[(i + 1) % 6])
    center = QtCore.QPointF(cx, cy)
    for i in (0, 2, 4):
        painter.drawLine(center, pts[i])
    painter.end()
    return QtGui.QIcon(pixmap)


def _draw_list_icon(size=96, color="white", stroke=6):
    """Side-nav icon for the JOB tab: clipboard with 3 lines."""
    pixmap, painter = _icon_painter(size, color, stroke)
    m = size * 0.16
    rect = QtCore.QRectF(m, m * 1.3, size - 2 * m, size - 2.3 * m)
    painter.drawRoundedRect(rect, 6, 6)
    tab_w = size * 0.32
    tab_rect = QtCore.QRectF(size / 2 - tab_w / 2, m * 0.35, tab_w, m * 0.9)
    painter.drawRoundedRect(tab_rect, 3, 3)
    for frac in (0.32, 0.56, 0.80):
        y = rect.top() + rect.height() * frac
        painter.drawLine(QtCore.QPointF(rect.left() + size * 0.10, y),
                          QtCore.QPointF(rect.right() - size * 0.10, y))
    painter.end()
    return QtGui.QIcon(pixmap)


def _draw_monitor_icon(size=96, color="white", stroke=6):
    """Side-nav icon for the SYSTEM tab: monitor + stand."""
    pixmap, painter = _icon_painter(size, color, stroke)
    m = size * 0.14
    cx = size / 2
    screen = QtCore.QRectF(m, m, size - 2 * m, size * 0.52)
    painter.drawRoundedRect(screen, 4, 4)
    stand_top = screen.bottom()
    stand_bottom = stand_top + size * 0.14
    painter.drawLine(QtCore.QPointF(cx, stand_top), QtCore.QPointF(cx, stand_bottom))
    base_w = size * 0.30
    painter.drawLine(QtCore.QPointF(cx - base_w / 2, stand_bottom),
                      QtCore.QPointF(cx + base_w / 2, stand_bottom))
    painter.end()
    return QtGui.QIcon(pixmap)


def _draw_power_icon(size=96, color="white", stroke=8):
    """Header icon for Exit/Shutdown: power symbol (ring with a top gap
    centered on the vertical tick, so it reads as symmetric at small
    sizes instead of lopsided)."""
    pixmap, painter = _icon_painter(size, color, stroke)
    cx, cy = size / 2, size / 2
    r = size * 0.30
    rect = QtCore.QRectF(cx - r, cy - r, 2 * r, 2 * r)
    gap = 32  # degrees of open gap, centered on top (90deg)
    painter.drawArc(rect, (90 + gap // 2) * 16, (360 - gap) * 16)
    painter.drawLine(QtCore.QPointF(cx, size * 0.16), QtCore.QPointF(cx, cy - r * 0.15))
    painter.end()
    return QtGui.QIcon(pixmap)


def _draw_zoom_center_icon(size=96, color="white", stroke=6):
    """Control-panel icon for Zoom Center: crosshair with corner brackets."""
    pixmap, painter = _icon_painter(size, color, stroke)
    cx, cy = size / 2, size / 2
    m = size * 0.16
    arm = size * 0.18
    corners = [
        ((m, m + arm), (m, m), (m + arm, m)),
        ((size - m - arm, m), (size - m, m), (size - m, m + arm)),
        ((m, size - m - arm), (m, size - m), (m + arm, size - m)),
        ((size - m - arm, size - m), (size - m, size - m), (size - m, size - m - arm)),
    ]
    for p1, p2, p3 in corners:
        painter.drawLine(QtCore.QPointF(*p1), QtCore.QPointF(*p2))
        painter.drawLine(QtCore.QPointF(*p2), QtCore.QPointF(*p3))
    cross = size * 0.10
    painter.drawLine(QtCore.QPointF(cx - cross, cy), QtCore.QPointF(cx + cross, cy))
    painter.drawLine(QtCore.QPointF(cx, cy - cross), QtCore.QPointF(cx, cy + cross))
    painter.end()
    return QtGui.QIcon(pixmap)


def _draw_bell_icon(size=96, color="white", stroke=6):
    """Side-nav icon for the ALARM tab: bell outline."""
    pixmap, painter = _icon_painter(size, color, stroke)
    cx = size / 2
    top = size * 0.20
    bottom = size * 0.72
    path = QtGui.QPainterPath()
    path.moveTo(cx - size * 0.26, bottom)
    path.cubicTo(cx - size * 0.26, top, cx + size * 0.26, top, cx + size * 0.26, bottom)
    path.lineTo(cx + size * 0.34, bottom)
    path.lineTo(cx - size * 0.34, bottom)
    path.closeSubpath()
    painter.drawPath(path)
    painter.drawLine(QtCore.QPointF(cx, top - size * 0.08), QtCore.QPointF(cx, top))
    painter.setBrush(QtGui.QColor(color))
    painter.drawEllipse(QtCore.QPointF(cx, bottom + size * 0.05), size * 0.045, size * 0.045)
    painter.end()
    return QtGui.QIcon(pixmap)


