        def _switch_checkbox(name):
            # QPushButton(checkable), not QCheckBox - reads "ON"/"OFF" as
            # plain text (same at-a-glance clarity as the combobox this
            # replaces) with a much bigger touch target than a checkbox
            # indicator. QPushButton shares QCheckBox's isChecked()/
            # setChecked()/toggled API (both are QAbstractButton), so
            # app.py's read/write sites don't need to know which it is.
            btn = QtWidgets.QPushButton(self.processingCard)
            btn.setObjectName(name)
            btn.setCheckable(True)
            btn.setChecked(True)
            btn.setText("ON")
            btn.setMinimumSize(QtCore.QSize(108, 48))
            btn.setMaximumSize(QtCore.QSize(108, 48))
            btn.setCursor(QtGui.QCursor(QtCore.Qt.PointingHandCursor))
            btn.toggled.connect(lambda checked, b=btn: b.setText("ON" if checked else "OFF"))
            return btn

