        self.cbbAutoCompare = _switch_checkbox("cbbAutoCompare")
        self.cbbUseKeypoint = _switch_checkbox("cbbUseKeypoint")
        self.cbbAutoReport = _switch_checkbox("cbbAutoReport")
        self.cbbUpsample = _switch_checkbox("cbbUpsample")

